#!/usr/bin/env bash
#
# A wizard — walks a human through a manual procedure step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library — delightful, consistent UX. Identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear — wipe the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" — opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later — it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" — clear the screen, then announce a stage and show progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." — a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." — a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL — open in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser — visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser — visit it manually: $url"
}

# pause "msg" — wait for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" — y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY — current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" — read a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" — like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE — upsert KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE — set a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name — gh not ready; set it later"
}

# set_var NAME VALUE — set a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name — gh not ready; set it later"
}

# finish — clear, then a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES — author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=9
REPOSITORY_ROOT=$(cd "$(dirname "$0")/../.." && pwd)
POLKIT_RULE_SRC="$REPOSITORY_ROOT/ops/polkit/50-voice-broker-bountywell.rules"
POLKIT_RULE_DST=/etc/polkit-1/rules.d/50-voice-broker-bountywell.rules
RECOVERY_SERVICE_SRC="$REPOSITORY_ROOT/ops/systemd/bountywell-api-recovery.service"
RECOVERY_TIMER_SRC="$REPOSITORY_ROOT/ops/systemd/bountywell-api-recovery.timer"
PR_URL=https://github.com/JacobStephens2/voice-agent/pull/45
PWA_URL=https://voice.stephens.page
RELEASE_FILE=/opt/voice-agent/current/.voice-agent-release
MERGE_COMMIT=""

require_merge_commit() {
  while [[ ! ${MERGE_COMMIT:-} =~ ^[0-9a-f]{40}$ ]]; do
    ask MERGE_COMMIT "Paste the 40-character Human Merge commit SHA:"
    MERGE_COMMIT=${MERGE_COMMIT//[$'\t\r\n ']/}
  done
}

detect_merged_commit() {
  local sha=""
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    sha=$(gh pr view 45 --json state,mergeCommit --jq \
      'if .state == "MERGED" then .mergeCommit.oid else empty end' 2>/dev/null || true)
  fi
  if [[ $sha =~ ^[0-9a-f]{40}$ ]]; then
    MERGE_COMMIT=$sha
  fi
}

require_javascript_polkit() {
  if [[ ! -d /etc/polkit-1/rules.d ]]; then
    warn "This host has no /etc/polkit-1/rules.d; a unit-filtered allowlist cannot be installed."
    exit 1
  fi
  if command -v dpkg-query >/dev/null 2>&1 && \
    dpkg-query -W -f '${Version}' policykit-1 2>/dev/null | grep -Eq '^0\.105'; then
    warn "polkit 0.105 ignores JavaScript rules and cannot unit-filter systemd actions."
    warn "Do not install a blanket manage-units grant. Upgrade polkit or stop here."
    exit 1
  fi
  if command -v dpkg-query >/dev/null 2>&1 && dpkg-query -W polkitd >/dev/null 2>&1; then
    note "polkitd is installed; JavaScript rules in /etc/polkit-1/rules.d will be used."
    return
  fi
  confirm "Does this Agent Host evaluate JavaScript rules in /etc/polkit-1/rules.d?" || exit 1
}

reload_polkit() {
  if systemctl cat polkit.service >/dev/null 2>&1; then
    sudo systemctl restart polkit.service
  elif systemctl cat polkitd.service >/dev/null 2>&1; then
    sudo systemctl restart polkitd.service
  else
    warn "Could not find polkit.service; rules are installed but may need a manual polkit restart."
  fi
}

as_voice_broker_systemctl() {
  sudo systemd-run --quiet --wait --pipe --collect \
    --uid=voice-broker --gid=voice-broker \
    /bin/systemctl --no-ask-password --no-pager "$@"
}

if [[ ! -e /opt/voice-agent ]]; then
  warn "Run this wizard on the Agent Host so Promotion, polkit, and deployment-health can be checked."
  exit 1
fi
if [[ ! -f $POLKIT_RULE_SRC ]]; then
  warn "Missing polkit rule at $POLKIT_RULE_SRC"
  exit 1
fi
if [[ ! -f $RECOVERY_SERVICE_SRC || ! -f $RECOVERY_TIMER_SRC ]]; then
  warn "Missing pinned recovery units under ops/systemd/"
  exit 1
fi

banner "Bountywell Outage Drill"

stage "Human Merge the drill software"
say "Production activation is Human Merge. Merge PR #45 as your authenticated GitHub user."
open_url "$PR_URL"
step "On the pull request, merge with your GitHub account. Do not push to main and do not let a bot merge."
step "Copy the resulting 40-character commit on main. Promotion uses that exact commit."
detect_merged_commit
if [[ $MERGE_COMMIT =~ ^[0-9a-f]{40}$ ]]; then
  note "Detected merged commit $MERGE_COMMIT"
else
  pause "Press Enter after the pull request is merged."
  detect_merged_commit
  require_merge_commit
fi
note "Human Merge commit is $MERGE_COMMIT"

stage "Confirm Promotion of the exact merge commit"
say "The Agent Host serializes verified Human Merges and promotes the exact merge commit."
while true; do
  current=""
  if [[ -f $RELEASE_FILE ]]; then
    current=$(tr -d '[:space:]' < "$RELEASE_FILE")
  fi
  if [[ $current == "$MERGE_COMMIT" ]]; then
    note "Active Release is $current"
    break
  fi
  note "Active Release is ${current:-none}. Waiting for $MERGE_COMMIT."
  pause "Press Enter to re-check Promotion."
done
sudo /usr/local/libexec/voice-agent/deployment-health.sh
note "Deployment health passed for $MERGE_COMMIT"

stage "Narrow the voice-broker systemd allowlist"
say "voice-broker may start and stop only bountywell-api.service and the independent recovery timer units."
say "A blanket manage-unit-files grant also authorizes StartUnit on this host, so link/disable stay with root."
say "This stage pins the recovery units under /etc/systemd/system/ and installs the unit-filtered polkit rule."
require_javascript_polkit
step "Install $RECOVERY_SERVICE_SRC and $RECOVERY_TIMER_SRC, then $POLKIT_RULE_SRC."
confirm "Pin the recovery units and install the voice-broker polkit rule on this host?" || exit 1
sudo install -m 0644 -o root -g root "$RECOVERY_SERVICE_SRC" \
  /etc/systemd/system/bountywell-api-recovery.service
sudo install -m 0644 -o root -g root "$RECOVERY_TIMER_SRC" \
  /etc/systemd/system/bountywell-api-recovery.timer
sudo systemctl daemon-reload
sudo install -m 0644 -o root -g root "$POLKIT_RULE_SRC" "$POLKIT_RULE_DST"
reload_polkit
denied_unit=apache2.service
if ! systemctl cat "$denied_unit" >/dev/null 2>&1; then
  denied_unit=cron.service
fi
if as_voice_broker_systemctl start "$denied_unit"; then
  warn "voice-broker was allowed to start $denied_unit. The allowlist is too wide. Stop and fix the polkit rule."
  exit 1
fi
note "voice-broker was denied start of $denied_unit."
if ! as_voice_broker_systemctl start bountywell-api.service; then
  warn "voice-broker could not start bountywell-api.service. Check the polkit rule and unit name."
  exit 1
fi
note "voice-broker may start bountywell-api.service."

stage "Perform a Fresh Passkey Action"
say "Only enrolling restart authority expands authority, so only it requires a Fresh Passkey Action. Arming, proving, injecting, and presenting run on the enrolled Standing Autonomy Policy. Use the passkey device, not this SSH session."
open_url "$PWA_URL"
step "Sign in with a passkey if the task list is not already open."
step "Choose “Perform Fresh Passkey Action” and complete the passkey ceremony."
pause "Press Enter after the PWA shows the Fresh Passkey Action validity time."

stage "Grant Bountywell restart authority"
open_url "$PWA_URL"
step "Choose “Grant Bountywell restart authority”."
step "Confirm bountywell-api.service is registered with the exact bountywell-api.service restart capability."
step "Voice, repository content, and the existing Trusted Browser Session must not be able to grant this."
pause "Press Enter after restart authority is visible."

stage "Arm the independent recovery timer"
open_url "$PWA_URL"
step "Choose “Arm recovery timer”."
step "Confirm the PWA says the independent recovery timer is armed for bountywell-api.service."
pause "Press Enter after the timer is armed."

stage "Prove the recovery timer"
say "Production proof inspects the recovery unit files for OnActiveSec=10min and systemctl start bountywell-api.service. It does not wait ten minutes."
open_url "$PWA_URL"
step "Choose “Prove recovery timer”."
step "Confirm the PWA says the recovery timer was proven capable of starting bountywell-api.service."
step "Confirm the drill Evidence Record reads “Is the guarded Bountywell Outage Drill ready?” with the conclusion “Bountywell Outage Drill is armed and ready.” It must not report a fault yet."
pause "Press Enter after the timer is proven."

stage "Start the guarded outage drill"
say "This stops only bountywell-api.service and then presents one sentence — “Bountywell's API appears unavailable.” — to the Voice Agent. Injection is refused unless a live Telephone Session is carrying you, and the ten-minute timer is the backstop if recovery fails."
open_url "$PWA_URL"
confirm "Are you on a live Telephone Session for the next ten minutes, with the recovery timer armed and proven?" || exit 1
step "Choose “Start guarded outage drill”."
step "If the PWA reports the fault report was not presented, choose “Present fault report again”: a stopped unit recovers nothing until the Voice Agent is told."
step "Remain at the Evidence Record. The worker diagnoses and recovers the presented Durable Task without being told the injected fault."
ask TASK_URL "Authenticated Evidence Record task link:"

stage "Inspect the Evidence Record"
open_url "$TASK_URL"
step "Confirm the question is “Bountywell's API appears unavailable.”"
step "Confirm the conclusion is “Bountywell API was recovered.”"
step "Confirm the timeline includes fault report, its presentation, inspected evidence, recorded hypotheses, policy decision, restart Operation, verification, timer lifecycle, and final conclusion."
step "Confirm you received the completion report — a Completion Callback or its Silent Notification — and not only this page."
step "Confirm it does not show raw logs, journal output, or secrets."
confirm "Does the Evidence Record show a successful guarded recovery?" || exit 1
health_status=$(curl -sS -o /dev/null -w '%{http_code}' --max-time 10 https://bountywell.com/api/health || true)
data_status=$(curl -sS -o /dev/null -w '%{http_code}' --max-time 10 https://bountywell.com/api/data || true)
if [[ $health_status == 200 && $data_status == 401 ]]; then
  note "Public /api/health is 200 and /api/data is 401."
else
  warn "Public endpoints are /api/health=$health_status /api/data=$data_status (expected 200 and 401)."
fi
say "Issue #11 stays open until you close it. Draft comment:"
printf '\n  Slice two (Bountywell Outage Drill) is accepted for immutable Release `%s`.\n' "$MERGE_COMMIT"
printf '\n  The Evidence Record is %s. Conclusion: Bountywell API was recovered.\n' "$TASK_URL"
printf '\n  The independent recovery timer was removed after verified service health and can no longer start the unit.\n\n'
note "Close https://github.com/JacobStephens2/voice-agent/issues/11 with that comment after you are satisfied. Then /clear before implementing #43 or #44."

finish
